// Test: nestedTemplateExtends
// Upstream's classes are empty; a getter per template parameter was added
// to BaseRepository so the bound arguments have something to observe.
namespace PsalmTest_template_nested_template_1 {
    interface IBaseViewData {}

    /**
     * @template TViewData
     */
    class BaseModel {}

    /**
     * @template TViewData as IBaseViewData
     * @template TModel as BaseModel<TViewData>
     */
    abstract class BaseRepository {
        /** @return TViewData */
        abstract public function viewData();
        /** @return TModel */
        abstract public function model();
    }

    class StudentViewData implements IBaseViewData {}
    class TeacherViewData implements IBaseViewData {}

    /** @extends BaseModel<StudentViewData> */
    class StudentModel extends BaseModel {}

    /** @extends BaseModel<TeacherViewData> */
    class TeacherModel extends BaseModel {}

    /** @extends BaseRepository<StudentViewData, StudentModel> */
    abstract class StudentRepository extends BaseRepository {}

    /** @extends BaseRepository<TeacherViewData, TeacherModel> */
    abstract class TeacherRepository extends BaseRepository {}

    function test(StudentRepository $students, TeacherRepository $teachers): void {
        assertType('StudentViewData', $students->viewData());
        assertType('StudentModel', $students->model());
        assertType('TeacherViewData', $teachers->viewData());
        assertType('TeacherModel', $teachers->model());
    }
}

// Test: unwrapIndirectGenericTemplated
namespace PsalmTest_template_nested_template_2 {
    class Payload {}

    /**
     * @template TInner
     */
    interface Wrapper {
        /** @return TInner */
        public function unwrap() : object;
    }

    /**
     * @template TInner2
     * @template TWrapper2 of Wrapper<TInner2>
     * @param  TWrapper2 $wrapper
     * @return TInner2
     */
    function indirectUnwrap(Wrapper $wrapper) : object {
        return unwrapGeneric($wrapper);
    }

    /**
     * @template TInner1
     * @template TWrapper1 of Wrapper<TInner1>
     * @param TWrapper1 $wrapper
     * @return TInner1
     */
    function unwrapGeneric(Wrapper $wrapper) {
        return $wrapper->unwrap();
    }

    /** @param Wrapper<Payload> $wrapper */
    function test(Wrapper $wrapper): void {
        assertType('Payload', $wrapper->unwrap());
        assertType('Payload', unwrapGeneric($wrapper));
        assertType('Payload', indirectUnwrap($wrapper));
    }
}

// Test: unwrapFromTemplatedClassString
namespace PsalmTest_template_nested_template_3 {
    /**
     * @template TInner
     */
    interface Wrapper {
        /** @return TInner */
        public function unwrap();
    }

    /**
     * @implements Wrapper<string>
     */
    class StringWrapper implements Wrapper {
        public function unwrap() {
            return "hello";
        }
    }

    /**
     * @template TInner
     * @template TWrapper of Wrapper<TInner>
     *
     * @param  class-string<TWrapper> $class
     * @return TInner
     */
    function load(string $class) {
        $package = new $class();
        return $package->unwrap();
    }

    $result = load(StringWrapper::class);
    assertType('string', $result);
}

// Test: unwrapNestedTemplateWithReset
namespace PsalmTest_template_nested_template_4 {
    class Item {}

    /**
     * @template TValue
     * @template TArray of non-empty-array<TValue>
     * @param TArray $arr
     * @return TValue
     */
    function toList(array $arr): array {
        return reset($arr);
    }

    /** @param non-empty-array<Item> $items */
