// Test: 3levelNestedTemplatesOfMixed
// Upstream's interfaces are empty; J gained a getter so the `@implements
// J<V>` and `@extends J<V>` bindings have something to observe.
namespace PsalmTest_template_nested_template_5 {
    class X {}

    /** @template T */
    interface A {}

    /**
     * @template T
     * @template U of A<T>
     */
    interface B {}

    /** @template T */
    interface J {
        /** @return T */
        public function get();
    }

    /**
     * @template T
     * @template U of A<T>
     * @implements J<U>
     */
    abstract class K2 implements J {}

    /**
     * @template T
     * @template U of A<T>
     * @template V of B<T, U>
     * @extends J<V>
     */
    interface K3 extends J {}

    /**
     * @template T
     * @template U of A<T>
     * @template V of B<T, U>
     * @implements J<V>
     */
    abstract class K1 implements J {}

    /**
     * @param K2<X, A<X>> $k2
     * @param K3<X, A<X>, B<X, A<X>>> $k3
     * @param K1<X, A<X>, B<X, A<X>>> $k1
     */
    function test(K2 $k2, K3 $k3, K1 $k1): void {
        assertType('A<X>', $k2->get());
        assertType('B<X, A<X>>', $k3->get());
        assertType('B<X, A<X>>', $k1->get());
    }
}

// Test: 4levelNestedTemplatesOfObjects
// A concrete subclass was added so the four-level chain of `@extends`
// bindings can be observed through the protected getter.
namespace PsalmTest_template_nested_template_6 {
    /**
     * @template T
     */
    interface DbEntity
    {
        /**
         * @return T
         */
        public function toCore();
    }

    /**
     * @template T of object
     */
    abstract class EntityRepository {}

    /**
     * @template T of object
     * @extends EntityRepository<T>
     */
    abstract class DbEntityRepository
    extends EntityRepository {}

    interface ObjectId {}

    /**
     * @template I of ObjectId
     */
    interface AnObject {}

    /**
     * @template I of ObjectId
     * @template O of AnObject<I>
     * @template E of DbEntity<O>
     * @extends DbEntityRepository<E>
     */
    abstract class AnObjectEntityRepository
    extends DbEntityRepository
    {}

    /**
     * @template T
     * @template E of DbEntity<T>
     * @template R of DbEntityRepository<E>
     */
    abstract class DbRepositoryWrapper
    {
        /** @var R $repo Db repository */
        private DbEntityRepository $repo;

        /**
         * @return DbEntityRepository The Db repository.
         * @psalm-return R
         */
        protected function getDbRepo(): DbEntityRepository
        {
            return $this->repo;
        }
    }

    /**
     * @template I of ObjectId
     * @template O of AnObject<I>
     * @template E of DbEntity<O>
     * @template R of AnObjectEntityRepository<I, O, E>
     * @extends DbRepositoryWrapper<O, E, R>
     */
    abstract class AnObjectDbRepositoryWrapper
    extends DbRepositoryWrapper {}

    class UserId implements ObjectId {}
    /** @implements AnObject<UserId> */
    class User implements AnObject {}
    /** @implements DbEntity<User> */
    abstract class UserEntity implements DbEntity {}
    /** @extends AnObjectEntityRepository<UserId, User, UserEntity> */
    abstract class UserEntityRepository extends AnObjectEntityRepository {}

    /** @extends AnObjectDbRepositoryWrapper<UserId, User, UserEntity, UserEntityRepository> */
    abstract class UserRepository extends AnObjectDbRepositoryWrapper {
        public function test(UserEntity $entity): void {
            assertType('UserEntityRepository', $this->getDbRepo());
            assertType('User', $entity->toCore());
        }
    }
}
